"""An asteroid belt: an orbit that holds up to ~1e16 asteroids, generated by sectors around the ship and never saved.

The belt is a toroid around the star: radial density parabolic across its half-width, vertical density a Gaussian
truncated at the half-thickness (both ratios of the belt's distance a0). The count of asteroids of MIN_DIAMETER or more
follows the size law (asteroid_sizes.py) and grows with a0 squared, times a drawn richness. As for the fixed stars
(fixed_stars.py), the belt's children are managed through sectors that are never seen: a Poisson count from the sector's
seed, a position inside the sector, and an identity that is the integer cell (CELL_SIZE) holding the asteroid, so a
collision loses the newcomer.

Cosmetic asteroids. Nearly all are rows of numpy arrays, regenerated from the seed whenever `near` needs them and never
remembered. They sit in sectors of orbital coordinates (a, angle, height): the belt shears, since each radius turns at
its own rate, so a sector keeps its asteroids and the query follows where it is at the date. An asteroid is on rails, a
circle of radius a at that rate, plus a constant peculiar velocity (a speed of a tenth of the circular one, on average):
it drifts along a segment of one sector's side, centred on its rail point, and wraps to the other end (a position that
jumps there, seen only by a pilot a few metres from it at that very instant). The density stays uniform and the speed
constant. Angles are those at the middle of an epoch of EPOCH_ORBIT_FRACTION of the belt's period, and the seeds hold
the epoch number: the shear a query has to allow for stays below a sector, and a new epoch re-draws the whole population
(a rare event for a pilot, and hidden by the time compression that brings it).

The tiers. One grid for all sizes would hold a hundred thousand 1 m rocks for each 100 m one, so every tier of
`AsteroidTier` (tiny to huge) has its own grid of "asteroidal sectors", whose side holds SECTOR_TARGET_COUNT asteroids
at the densest point. A query gives a reach for each tier it wants (`near`): a few sectors of that tier, whatever their
size.

Relevant asteroids. The ones the player follows are promoted (`promote`): the cosmetic one leaves the results and an
`Asteroid` takes its place, on a full elliptical orbit. They are kept in `relevant` and saved as the belt's alterations:
only their keys and scans, as the rest is derived from the keys. `build` makes the `Asteroid` of a key without
promoting it (a mission can name it in an offer), and `random_key` draws the key of a cosmetic asteroid from the
belt's density.
"""

from __future__ import annotations

import logging
import math
import random
from collections import OrderedDict
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import datetime
from typing import TYPE_CHECKING, ClassVar

import numpy as np

from common.units import format_compact_distance
from common.vector3 import Vector3
from galaxies import seeds
from galaxies.asteroid import Asteroid, AsteroidKey
from galaxies.asteroid_sizes import MIN_DIAMETER, AsteroidTier, generated_count, sample_diameters, tier_share
from galaxies.orbit import Orbit
from galaxies.orbit_layout import OrbitKind
from galaxies.world import World

if TYPE_CHECKING:
    from galaxies.stellar_system import StellarSystem

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class SectorRows:
    """The cosmetic asteroids of one sector: one entry in each array."""
    semi_major_axis: np.ndarray  # m: the radius of the rail
    angle: np.ndarray  # rad: along the rail, at the middle of the epoch
    height: np.ndarray  # m: above the reference plane
    diameter: np.ndarray  # m
    speed: np.ndarray  # m/s: peculiar
    direction: np.ndarray  # (n, 3) unit vectors of the peculiar velocity
    phase: np.ndarray  # [0, 1): where the drift segment begins
    cell: np.ndarray  # (n, 3) integer cell, the identity inside the sector
    # rad/s: how fast the rail turns, from its radius (kept to spare a power and a root at every query)
    rate: np.ndarray

    def take(self, indices: np.ndarray) -> SectorRows:
        return SectorRows(
            self.semi_major_axis[indices], self.angle[indices], self.height[indices], self.diameter[indices],
            self.speed[indices], self.direction[indices], self.phase[indices], self.cell[indices], self.rate[indices])


@dataclass(frozen=True)
class TierGrid:
    """The sectors of a tier: cubes of `side` in a and height, and `arcs` equal slices of the turn."""
    share: float  # of the generated asteroids
    side: float  # m
    arcs: int
    arc_angle: float  # rad


@dataclass(frozen=True)
class NearAsteroids:
    """Cosmetic asteroids found by `AsteroidBelt.near`, in the reference frame (positions in m, velocities in m/s)."""
    position: np.ndarray  # (n, 3)
    velocity: np.ndarray  # (n, 3)
    diameter: np.ndarray  # (n,)
    key: np.ndarray  # (n, 8) ints, the values of an `AsteroidKey`: see `asteroid_key`

    @staticmethod
    def empty() -> NearAsteroids:
        return NearAsteroids(np.zeros((0, 3)), np.zeros((0, 3)), np.zeros(0), np.zeros((0, 8), dtype=np.int64))

    @staticmethod
    def join(parts: list[NearAsteroids]) -> NearAsteroids:
        if not parts:
            return NearAsteroids.empty()
        return NearAsteroids(
            np.concatenate([part.position for part in parts]), np.concatenate([part.velocity for part in parts]),
            np.concatenate([part.diameter for part in parts]), np.concatenate([part.key for part in parts]))

    def asteroid_key(self, index: int) -> AsteroidKey:
        return AsteroidKey.from_ints(self.key[index])


class AsteroidBelt(Orbit):
    """An orbit whose asteroids are generated by sectors (see the module docstring)."""

    # The toroid: ratios of the belt's distance, and the count.
    HALF_WIDTH_RATIO = 0.22  # the main belt spans 2.1 to 3.3 of 2.7
    HALF_THICKNESS_RATIO = 0.1
    THICKNESS_SIGMAS = 2.0  # the half-thickness, in sigmas of the vertical Gaussian
    REFERENCE_DISTANCE = 4.0e11  # m: the main belt, of which the size law gives the count
    RICHNESS_SIGMA = 0.5  # of the logarithm of the count's factor

    # Sectors.
    # Asteroids in a sector at the densest point: measured (50 to 2000) to give the cheapest queries.
    SECTOR_TARGET_COUNT = 100
    CELL_SIZE = 1.0e5  # m: an asteroid's identity inside its sector (a collision chance of ~1e-6 for the tiny)
    SECTOR_CACHE_SIZE = 1024  # sectors of a few kilobytes each: several times the window of a wide query
    MAX_QUERY_SECTORS = 2000  # a query for more is refused: it would build millions of asteroids
    # Reaches (m) for `near`, measured at ~1.6 ms (display) and ~8 ms (scanner) a query once the sectors are made, ~40
    # and ~110 ms the first time. Display: what is shown without a scan, only if it is also slow: within 1e6 m of a ship
    # in the belt there is usually no tiny rock, within 1e7 m a few dozen. Scanner: while a scan is active.
    DISPLAY_REACHES: ClassVar[dict[AsteroidTier, float]] = {AsteroidTier.TINY: 1.0e7, AsteroidTier.SMALL: 1.0e7}
    SCANNER_REACHES: ClassVar[dict[AsteroidTier, float]] = {
        AsteroidTier.TINY: 1.0e7, AsteroidTier.SMALL: 1.0e8, AsteroidTier.MEDIUM: 1.0e9, AsteroidTier.BIG: 1.0e10}

    # Motion.
    EPOCH_ORBIT_FRACTION = 0.1  # of the belt's period
    DRIFT_SPEED_FRACTION = 0.1  # of the circular speed: the scale of the peculiar speeds
    MAX_DRIFT_SPEED_FRACTION = 0.5
    SHEAR_MARGIN = 2.0  # on the angle a slice of the belt shears, for the first-order estimate

    def __init__(self, parent_stellar_system: StellarSystem, number: float, kind: OrbitKind, distance_from_star: float,
                 saved_alterations: dict) -> None:
        super().__init__(parent_stellar_system, number, kind, distance_from_star, saved_alterations)
        a0 = distance_from_star
        self.gravitational_parameter: float = World.GRAVITATIONAL_CONSTANT * parent_stellar_system.star.mass
        self.circular_speed: float = math.sqrt(self.gravitational_parameter / a0)
        self.epoch_length: float = self.EPOCH_ORBIT_FRACTION * math.tau * a0 / self.circular_speed  # s

        my_random = random.Random(self.seed)
        self.richness: float = math.exp(my_random.gauss(0.0, AsteroidBelt.RICHNESS_SIGMA))

        self.half_width: float = AsteroidBelt.HALF_WIDTH_RATIO * a0
        self.inner: float = a0 - self.half_width
        self.outer: float = a0 + self.half_width
        self.half_thickness: float = AsteroidBelt.HALF_THICKNESS_RATIO * a0
        self.sigma: float = self.half_thickness / AsteroidBelt.THICKNESS_SIGMAS  # of the vertical Gaussian

        self.count: float = generated_count() * self.richness * (a0 / AsteroidBelt.REFERENCE_DISTANCE) ** 2
        radial_total = self._radial_integral(self.inner, self.outer)
        vertical_total = self._vertical_integral(-self.half_thickness, self.half_thickness)
        self.peak_density: float = self.count / (math.tau * radial_total * vertical_total)  # per m3
        self.grids: dict[AsteroidTier, TierGrid] = {tier: self._grid_of(tier) for tier in AsteroidTier}

        self._sectors: OrderedDict[tuple[int, int, int, int, int], SectorRows] = OrderedDict()
        self.relevant: dict[AsteroidKey, Asteroid] = {}
        for text, saved in (self.saved_alterations or {}).get('asteroids', {}).items():
            key = AsteroidKey.from_ints(text.split())
            self.relevant[key] = self.build(key).apply_alterations(saved)

        logger.info(
            f"Asteroid belt {self.number}: {self.count:.3g} asteroids of {MIN_DIAMETER:.0f} m or more, richness "
            f"{self.richness:.2f}; sector side per tier " + ", ".join(
                f"{tier.name.lower()} {format_compact_distance(grid.side)}" for tier, grid in self.grids.items()) + ".")

    # region Shape
    def _grid_of(self, tier: AsteroidTier) -> TierGrid:
        share = tier_share(tier)
        side = (AsteroidBelt.SECTOR_TARGET_COUNT / (self.peak_density * share)) ** (1.0 / 3.0)
        side = math.ceil(side / AsteroidBelt.CELL_SIZE) * AsteroidBelt.CELL_SIZE
        arcs = max(1, round(math.tau * self.distance_from_star / side))
        return TierGrid(share, side, arcs, math.tau / arcs)

    def _radial_integral(self, low: float, high: float) -> float:
        """The integral of a * (1 - x^2) da from `low` to `high` (x: the distance from the belt's middle, in
        half-widths): the radial density, times the radius that the turn adds."""
        a0, width = self.distance_from_star, self.half_width

        def antiderivative(a: float) -> float:
            u = a - a0
            return a0 * u + u * u / 2.0 - a0 * u ** 3 / (3.0 * width ** 2) - u ** 4 / (4.0 * width ** 2)

        return antiderivative(high) - antiderivative(low)

    def _vertical_integral(self, low: float, high: float) -> float:
        """The integral of the vertical Gaussian (peak 1) from `low` to `high`."""
        scale = self.sigma * math.sqrt(2.0)
        return self.sigma * math.sqrt(math.pi / 2.0) * (math.erf(high / scale) - math.erf(low / scale))
    # endregion

    # region Sectors
    def _sector(self, tier: AsteroidTier, epoch: int, ia: int, it: int, iz: int) -> SectorRows:
        """The cosmetic asteroids of a sector, from the cache or newly made."""
        cache_key = (tier.index, epoch, ia, it, iz)
        rows = self._sectors.get(cache_key)
        if rows is None:
            rows = self._make_sector(tier, epoch, ia, it, iz)
            self._sectors[cache_key] = rows
            if len(self._sectors) > AsteroidBelt.SECTOR_CACHE_SIZE:
                self._sectors.popitem(last=False)
        else:
            self._sectors.move_to_end(cache_key)
        return rows

    def _make_sector(self, tier: AsteroidTier, epoch: int, ia: int, it: int, iz: int) -> SectorRows:
        """Draws the asteroids of a sector from its seed, in a fixed order (a new draw goes last): count, radius, angle,
        height, diameter, speed, direction, phase."""
        grid = self.grids[tier]
        a_low, a_high = max(ia * grid.side, self.inner), min((ia + 1) * grid.side, self.outer)
        z_low, z_high = max(iz * grid.side, -self.half_thickness), min((iz + 1) * grid.side, self.half_thickness)
        if a_high <= a_low or z_high <= z_low:
            return self._empty_rows()
        my_random = np.random.default_rng(seeds.derive(self.seed, 'sector', tier.index, epoch, ia, it, iz))
        mean = self.peak_density * grid.share * self._radial_integral(a_low, a_high) * grid.arc_angle \
            * self._vertical_integral(z_low, z_high)
        count = int(my_random.poisson(mean))
        if count == 0:
            return self._empty_rows()

        a0 = self.distance_from_star
        semi_major_axis = self._draw_weighted(my_random, count, a_low, a_high, self._radial_weight, self.outer)
        angle = (it + my_random.random(count)) * grid.arc_angle
        height = self._draw_weighted(my_random, count, z_low, z_high, self._vertical_weight, 1.0)
        diameter = sample_diameters(tier, my_random, count)
        speed = np.minimum(my_random.rayleigh(AsteroidBelt.DRIFT_SPEED_FRACTION * self.circular_speed, count),
                           AsteroidBelt.MAX_DRIFT_SPEED_FRACTION * self.circular_speed)
        direction = my_random.normal(size=(count, 3))
        direction /= np.linalg.norm(direction, axis=1)[:, None]
        phase = my_random.random(count)
        cell = np.floor(np.stack([semi_major_axis, angle * a0, height], axis=1)
                        / AsteroidBelt.CELL_SIZE).astype(np.int64)

        rate = np.sqrt(self.gravitational_parameter / semi_major_axis ** 3)
        rows = SectorRows(semi_major_axis, angle, height, diameter, speed, direction, phase, cell, rate)
        order = np.lexsort((cell[:, 2], cell[:, 1], cell[:, 0]))  # stable: asteroids of one cell keep their draw order
        taken = np.all(cell[order[1:]] == cell[order[:-1]], axis=1)
        if not taken.any():
            return rows
        keep = np.ones(count, dtype=bool)
        keep[order[1:][taken]] = False  # a taken cell loses the newcomer
        return rows.take(np.flatnonzero(keep))

    def _radial_weight(self, radius: np.ndarray) -> np.ndarray:
        """The density across the belt, times the radius that the turn adds (the weight of a radius in a draw)."""
        return radius * (1.0 - ((radius - self.distance_from_star) / self.half_width) ** 2)

    def _vertical_weight(self, height: np.ndarray) -> np.ndarray:
        return np.exp(-height * height / (2.0 * self.sigma ** 2))

    @staticmethod
    def _draw_weighted(my_random: np.random.Generator, count: int, low: float, high: float, weight,
                       weight_max: float) -> np.ndarray:
        """`count` values in [low, high] with a density proportional to `weight`, by rejection."""
        result = np.empty(0)
        while result.size < count:
            candidates = my_random.uniform(low, high, size=2 * (count - result.size) + 8)
            accepted = my_random.random(candidates.size) * weight_max <= weight(candidates)
            result = np.concatenate([result, candidates[accepted]])
        return result[:count]

    @staticmethod
    def _empty_rows() -> SectorRows:
        return SectorRows(np.zeros(0), np.zeros(0), np.zeros(0), np.zeros(0), np.zeros(0), np.zeros((0, 3)),
                          np.zeros(0), np.zeros((0, 3), dtype=np.int64), np.zeros(0))
    # endregion

    # region Query
    def time_in_epoch(self, current_datetime: datetime) -> tuple[int, float]:
        """The epoch number of a date, and the seconds from the middle of that epoch."""
        # Local: as World does, the game environment needs the galaxy to load.
        from game_environment import GameEnvironment
        seconds = (current_datetime - GameEnvironment.EPOCH).total_seconds()
        epoch = math.floor(seconds / self.epoch_length + 0.5)
        return epoch, seconds - epoch * self.epoch_length

    def near(self, position: Vector3, current_datetime: datetime,
             reaches: Mapping[AsteroidTier, float] | None = None) -> NearAsteroids:
        """The cosmetic asteroids around a position (reference frame) at the date, with their positions and velocities.
        `reaches` gives the distance in metres to look for each tier: a tier that is not in it is not asked (so a
        scanner asks for tiny rocks within a few thousand kilometres and for medium ones much farther). By default it is
        DISPLAY_REACHES; SCANNER_REACHES is for a scan. The result is meant to be kept and asked again only after the
        ship has moved a fraction of a sector or some seconds have passed. A tier whose window would need more than
        MAX_QUERY_SECTORS sectors is left out (logged). The relevant asteroids are not here: they are in `relevant`."""
        epoch, local_seconds = self.time_in_epoch(current_datetime)
        if reaches is None:
            reaches = AsteroidBelt.DISPLAY_REACHES
        parts: list[NearAsteroids] = []
        for tier, radius in reaches.items():
            part = self._near_in_tier(tier, position, radius, epoch, local_seconds)
            if part is not None:
                parts.append(part)
        found = NearAsteroids.join(parts)
        for key in self.relevant:  # promoted: no longer cosmetic
            found = self._without(found, key)
        return found

    def _near_in_tier(self, tier: AsteroidTier, centre: Vector3, radius: float, epoch: int,
                      local_seconds: float) -> NearAsteroids | None:
        grid = self.grids[tier]
        reach = radius + grid.side / 2.0  # the drift takes an asteroid up to half a sector from its rail point
        ship_radius = math.hypot(centre.x, centre.y)
        ship_angle = math.atan2(centre.y, centre.x)
        a_low, a_high = max(ship_radius - reach, self.inner), min(ship_radius + reach, self.outer)
        z_low, z_high = max(centre.z - reach, -self.half_thickness), min(centre.z + reach, self.half_thickness)
        if a_low > a_high or z_low > z_high:
            return None
        half_angle = math.pi if reach >= ship_radius else math.asin(reach / ship_radius)

        sectors: list[tuple[int, int, int]] = []
        layers = range(math.floor(z_low / grid.side), math.floor(z_high / grid.side) + 1)
        for ia in range(math.floor(a_low / grid.side), math.floor(a_high / grid.side) + 1):
            slice_low, slice_high = max(ia * grid.side, self.inner), min((ia + 1) * grid.side, self.outer)
            rate = math.sqrt(self.gravitational_parameter / ((slice_low + slice_high) / 2.0) ** 3)
            shear = (AsteroidBelt.SHEAR_MARGIN * 1.5 * rate * (slice_high - slice_low) / 2.0 / slice_low
                     * abs(local_seconds))
            half = half_angle + shear
            centre_angle = ship_angle - rate * local_seconds  # where the asteroids that are at the ship's angle began
            first = math.floor((centre_angle - half) / grid.arc_angle)
            last = math.floor((centre_angle + half) / grid.arc_angle)
            arcs = (range(grid.arcs) if last - first + 1 >= grid.arcs
                    else dict.fromkeys(i % grid.arcs for i in range(first, last + 1)))
            sectors.extend((ia, it, iz) for it in arcs for iz in layers)
            if len(sectors) > AsteroidBelt.MAX_QUERY_SECTORS:
                logger.warning(f"Asteroid query refused: {tier.name.lower()} window of {radius:.3g} m needs over "
                               f"{AsteroidBelt.MAX_QUERY_SECTORS} sectors.")
                return None

        rows_list: list[SectorRows] = []
        prefixes: list[tuple[int, ...]] = []
        for ia, it, iz in sectors:
            rows = self._sector(tier, epoch, ia, it, iz)
            if rows.diameter.size:
                rows_list.append(rows)
                prefixes.append((tier.index, epoch, ia, it, iz))
        if not rows_list:
            return None
        rows = SectorRows(*(np.concatenate([getattr(part, name) for part in rows_list])
                            for name in SectorRows.__dataclass_fields__))
        sector_of_row = np.repeat(np.arange(len(rows_list)), [part.diameter.size for part in rows_list])

        # Most rows are far: drop them without trigonometry. A rail point is within `reach` of the ship (the asteroid is
        # within `radius`, and the drift moves it at most half a sector), so its radius, its height and, since the
        # distance between two points is at least 2 sqrt(a r) sin(angle / 2), its angle are limited. sin(x) >= 2 x / pi
        # gives the angle's bound.
        turn = (rows.angle + rows.rate * local_seconds - ship_angle + math.pi) % math.tau - math.pi
        angle_bound = math.pi * reach / (2.0 * np.sqrt(rows.semi_major_axis * max(ship_radius, 1.0)))
        possible = np.flatnonzero((np.abs(rows.semi_major_axis - ship_radius) <= reach)
                                  & (np.abs(rows.height - centre.z) <= reach) & (np.abs(turn) <= angle_bound))
        rows, sector_of_row = rows.take(possible), sector_of_row[possible]
        keys = np.hstack([np.array(prefixes, dtype=np.int64)[sector_of_row], rows.cell])

        position, velocity = self._rails(rows, local_seconds, grid.side)
        offset = position - np.array([centre.x, centre.y, centre.z])
        near = np.flatnonzero(np.sum(offset ** 2, axis=1) <= radius * radius)
        return NearAsteroids(position[near], velocity[near], rows.diameter[near], keys[near])

    def _rails(self, rows: SectorRows, local_seconds: float, side: float) -> tuple[np.ndarray, np.ndarray]:
        """Positions and velocities of cosmetic asteroids, a pure function of the time since the middle of the epoch:
        on the rail turning at its own rate, plus the drift along its segment of one sector's side."""
        a, rate = rows.semi_major_axis, rows.rate
        angle = rows.angle + rate * local_seconds
        sin, cos = np.sin(angle), np.cos(angle)
        position = np.stack([a * cos, a * sin, rows.height], axis=1)
        velocity = np.stack([-a * rate * sin, a * rate * cos, np.zeros(a.size)], axis=1)
        drift = (np.mod(local_seconds * rows.speed / side + rows.phase, 1.0) - 0.5) * side
        return position + drift[:, None] * rows.direction, velocity + rows.speed[:, None] * rows.direction

    @staticmethod
    def _without(found: NearAsteroids, key: AsteroidKey) -> NearAsteroids:
        values = np.array([key.tier, key.epoch, *key.sector, *key.cell], dtype=np.int64)
        keep = np.flatnonzero(~np.all(found.key == values, axis=1))
        return NearAsteroids(found.position[keep], found.velocity[keep], found.diameter[keep], found.key[keep])
    # endregion

    # region Relevant asteroids
    def random_key(self, my_random: random.Random, tier: AsteroidTier, epoch: int) -> AsteroidKey | None:
        """The key of a cosmetic asteroid of the tier in a random place of the belt (drawn from its density), in the
        epoch; a random one of those in the sector of that place. None if the sector has none. Nothing is changed."""
        grid = self.grids[tier]
        generator = np.random.default_rng(my_random.getrandbits(64))
        radius = self._draw_weighted(generator, 1, self.inner, self.outer, self._radial_weight, self.outer)[0]
        height = self._draw_weighted(
            generator, 1, -self.half_thickness, self.half_thickness, self._vertical_weight, 1.0)[0]
        arc = math.floor(generator.random() * grid.arcs)
        sector = (math.floor(radius / grid.side), arc, math.floor(height / grid.side))
        rows = self._sector(tier, epoch, *sector)
        if rows.diameter.size == 0:
            return None
        cell = rows.cell[my_random.randrange(rows.diameter.size)]
        return AsteroidKey(tier.index, epoch, sector, tuple(int(c) for c in cell))

    def build(self, key: AsteroidKey) -> Asteroid:
        """The `Asteroid` of a key, made now and not promoted: the belt is as it was (use `promote` to keep it). A new
        object at each call, a pure function of the key. Raises KeyError if the key's sector has no such asteroid."""
        tier = tuple(AsteroidTier)[key.tier]
        rows = self._sector(tier, key.epoch, *key.sector)
        found = np.flatnonzero(np.all(rows.cell == key.cell, axis=1))
        if found.size == 0:
            raise KeyError(f"No asteroid {key} in the belt {self.number}.")
        return Asteroid.of_belt(self, key, float(rows.semi_major_axis[found[0]]), float(rows.diameter[found[0]]))

    def promote(self, key: AsteroidKey) -> Asteroid:
        """The asteroid of the key as a relevant one (it was cosmetic until now); the belt is marked as altered."""
        asteroid = self.relevant.get(key)
        if asteroid is None:
            asteroid = self.build(key)
            self.relevant[key] = asteroid
            self.set_altered()
        return asteroid

    def get_alterations(self) -> dict | None:
        if not self.relevant:
            return None
        return {'asteroids': {str(key): asteroid.get_alterations() for key, asteroid in self.relevant.items()}}
    # endregion
